#!/usr/bin/env python3
"""
add_powershell_lessons.py

Scaffolds the powershell/ lesson folder (README, glossary, 7 lessons, scripts/
placeholder) into the Azure-Platform-Foundation repo.

Idempotent: existing files are left untouched and reported as skipped, same
convention as every other script in python-scripts/. Safe to re-run.

Usage:
    python3 add_powershell_lessons.py
"""

from pathlib import Path

# This script lives in python-scripts/, one level below repo root — resolve
# from the script's own location, not the current working directory.
SCRIPT_DIR = Path(__file__).resolve().parent
REPO_ROOT = SCRIPT_DIR.parent

FILES = {
    'powershell/README.md': "# PowerShell — Lessons\n\nFoundational PowerShell curriculum, built from zero, aimed at AZ-104 and real Azure administration. Read in order — each lesson assumes the ones before it.\n\n1. [Fundamentals](lessons/01-fundamentals.md) — what PowerShell is, the help system, running scripts on RHEL\n2. [Variables and Data Types](lessons/02-variables-and-data-types.md)\n3. [The Pipeline and Objects](lessons/03-pipeline-and-objects.md) — the concept that makes PowerShell different from Bash\n4. [Control Flow](lessons/04-control-flow.md) — if/switch/loops\n5. [Functions and Parameters](lessons/05-functions-and-parameters.md)\n6. [Connecting to Azure](lessons/06-connecting-to-azure.md) — Az module, Microsoft Graph, authentication\n7. [Script Structure and Your First Automation Script](lessons/07-script-structure-and-first-automation-script.md) — error handling, plus a full worked script built line by line\n\n`GLOSSARY.md` collects every term across all seven lessons in one place.\n\n## How this fits the rest of the repo\n\nThis is the foundation — read once, reference as needed. The **weekend study guide** (`powershell-weekend-study-guide.md`, already in the repo root) is the weekly practice ritual: every Saturday, pick a resource type from that week's Azure lab and write a script against it using what these lessons taught. Lessons teach the language; the weekend guide is where it gets used against real, freshly-built resources.\n\n## Suggested placement\n\nMatches the existing `python-scripts/` convention at repo root:\n\n```\nAzure-Platform-Foundation/\n├── powershell/\n│   ├── README.md\n│   ├── GLOSSARY.md\n│   └── lessons/\n│       ├── 01-fundamentals.md\n│       ├── 02-variables-and-data-types.md\n│       ├── 03-pipeline-and-objects.md\n│       ├── 04-control-flow.md\n│       ├── 05-functions-and-parameters.md\n│       ├── 06-connecting-to-azure.md\n│       └── 07-script-structure-and-first-automation-script.md\n├── python-scripts/\n├── powershell-weekend-study-guide.md\n└── python-weekend-study-guide.md\n```\n\nAs you write your own weekly scripts (starting from Lesson 7's pattern), a `powershell/scripts/` folder alongside `lessons/` would mirror how `python-scripts/` already holds your own work — naming's your call.\n",
    'powershell/GLOSSARY.md': '# PowerShell Glossary\n\nTerms from Lessons 1–7, in the order they first come up.\n\n- **Shell**: an interactive command environment — type a command, see output. PowerShell is a shell and a scripting language at once.\n- **Cmdlet**: a built-in PowerShell command, always named Verb-Noun (`Get-AzVM`, `New-AzResourceGroup`).\n- **`.ps1` file**: a saved PowerShell script.\n- **`pwsh`**: the PowerShell 7 executable on Linux/RHEL (as opposed to `powershell`, which is Windows PowerShell 5.1 and doesn\'t exist on Linux).\n- **Execution policy**: a Windows-only restriction on running scripts; not enforced by default on Linux, so `.ps1` files run without the policy errors Windows beginners commonly hit.\n- **`Get-Help`**: shows documentation for any cmdlet, including your own scripts if they have comment-based help.\n- **`Get-Command`**: searches for cmdlets by name or wildcard.\n- **`Get-Member`**: lists every property and method on whatever object is piped into it — the main tool for discovering what an object contains.\n- **Variable**: `$name = value`. Dynamically typed — no type declared up front.\n- **String interpolation**: embedding a variable directly in a double-quoted string (`"Hello $name"`); doesn\'t happen in single-quoted strings.\n- **`$()` subexpression**: wraps an expression (a property, a method call) so it can be embedded inside a string.\n- **Array**: an ordered list, `@("a", "b", "c")`. Fixed-size under the hood — `+=` creates a new array, not an in-place append.\n- **Hashtable**: key-value pairs, `@{ Key = "value" }` — PowerShell\'s equivalent of a Python dict.\n- **Pipeline**: passing the output object of one cmdlet as input to the next, via `|`.\n- **Object** (vs. text stream): structured data with named properties — the core difference between PowerShell and Bash.\n- **`$_`**: "the current object in the pipeline" — used inside script blocks passed to `Where-Object`, `ForEach-Object`, etc.\n- **`Where-Object`**: filters pipeline objects by a condition.\n- **`Select-Object`**: picks specific properties, or the first/last N objects, from the pipeline.\n- **`Sort-Object`**: sorts pipeline objects by a property.\n- **`ForEach-Object`**: cmdlet that runs a script block once per pipeline object, as it flows through.\n- **`foreach`**: language keyword that loops over a collection already loaded in memory — distinct from the `ForEach-Object` cmdlet above.\n- **Calculated property**: `@{Name="Label"; Expression={...}}` inside `Select-Object` — defines a new output column instead of just picking an existing one.\n- **Function**: a named, reusable block of PowerShell code, declared with `function Verb-Noun { ... }`.\n- **`param()`**: declares what a function or script accepts as input.\n- **Mandatory parameter**: `[Parameter(Mandatory = $true)]` — PowerShell refuses to run without a value supplied.\n- **`[CmdletBinding()]`**: turns a plain function into an advanced function that supports common parameters like `-Verbose` and `-WhatIf`.\n- **`ShouldProcess` / `-WhatIf`**: built-in dry-run support for functions marked `SupportsShouldProcess` — the PowerShell equivalent of `az deployment group what-if`.\n- **Context** (`Get-AzContext`): the currently authenticated account, tenant, and subscription that Az cmdlets operate against.\n- **`Connect-AzAccount`**: authenticates the session against Azure Resource Manager.\n- **Service principal**: an application identity used for unattended/automated authentication, instead of a personal login.\n- **Managed identity**: an identity Azure automatically assigns to a resource (VM, Function App), removing the need to store any secret at all.\n- **Microsoft Graph PowerShell SDK**: separate module from Az, used for Entra ID (`Get-MgUser`, `Get-MgGroup`) — talks to the Graph API rather than Azure Resource Manager.\n- **Scope** (Graph): a specific permission requested when connecting (`Connect-MgGraph -Scopes \'User.Read.All\'`) — request only what a script actually needs.\n- **Comment-based help**: the `<# .SYNOPSIS ... #>` block at the top of a script that makes `Get-Help` work on it.\n- **Terminating vs. non-terminating error**: terminating errors stop the script and are catchable with `try/catch`; non-terminating errors print a warning and continue unless forced to stop with `-ErrorAction Stop`.\n- **`-ErrorAction Stop`**: forces a normally non-terminating cmdlet failure to become catchable.\n- **Exit code**: `exit 0` (success) or `exit 1` (failure) — how a script signals success/failure to anything calling it, without parsing output text.\n',
    'powershell/lessons/01-fundamentals.md': '# Lesson 1 — Fundamentals\n\n## What PowerShell actually is\n\nPowerShell is two things at once: an interactive **shell** (like Bash — you type a command, it runs, you see output) and a full **scripting language** (you can save a sequence of commands to a file and run the whole thing at once). It was built by Microsoft on top of .NET, which is why — unlike Bash — its commands pass structured data around instead of plain text. That single fact shapes almost everything else in this lesson set, and it\'s covered properly in Lesson 3.\n\n## Why it matters here specifically\n\nAZ-104 tests Portal, CLI, and PowerShell administration — not Bicep authoring. PowerShell is also the tool most real Azure admin work runs on day to day: bulk operations, scheduled checks, anything you\'d do by hand in the Portal a hundred times and don\'t want to. Learning it isn\'t a side quest — it\'s a core AZ-104 skill and a core Cloud Engineer skill, which is why it\'s getting the same depth of treatment as the Bicep side of this repo.\n\n## Interactive vs. script\n\n- **Interactive**: you type a command directly into the terminal (`pwsh` on RHEL) and it runs immediately. Good for exploring, checking one thing, testing a single line before it goes into a script.\n- **Script**: a `.ps1` file containing a sequence of commands, saved and run as a unit. This is what "automation" means in practice — the whole point of a script is that you write it once and it does the same correct sequence of steps every time, instead of you retyping commands and risking a mistake on the tenth run.\n\nOn RHEL, PowerShell 7 runs as `pwsh`, not `powershell` (that name is Windows PowerShell 5.1, which doesn\'t exist on Linux). To run a script:\n\n```bash\npwsh ./my-script.ps1\n```\n\nUnlike Windows, Linux doesn\'t enforce PowerShell\'s "execution policy" restrictions by default — you won\'t hit the classic "scripts are disabled on this system" error that trips up Windows beginners. You can run `.ps1` files directly once they\'re on disk.\n\n## The help system — how to not memorize everything\n\nYou are not expected to know every cmdlet (PowerShell\'s term for a built-in command — covered fully in Lesson 3). You\'re expected to know how to find out what a cmdlet does, right from the terminal:\n\n```powershell\nGet-Help Get-AzVM              # shows syntax, description, examples\nGet-Help Get-AzVM -Examples    # just the usage examples\nGet-Help Get-AzVM -Full        # everything, including every parameter\n```\n\n```powershell\nGet-Command -Module Az.Compute # lists every cmdlet in a given module\nGet-Command *VM*               # search by wildcard if you don\'t know the exact name\n```\n\n```powershell\nGet-Member                     # run after any command, piped in — shows every\n                                # property and method on the object it returned\n```\n\n`Get-Member` gets its own full explanation in Lesson 3 once objects have been introduced properly, but know now that it exists — it\'s the single most useful "I don\'t know what this thing is" command in PowerShell.\n\n## What\'s next\n\nLesson 2 covers variables and data types — the building blocks any script needs before it can do anything useful.\n',
    'powershell/lessons/02-variables-and-data-types.md': '# Lesson 2 — Variables and Data Types\n\n## Variables\n\nEvery variable starts with `$`. No `let`, `var`, or `const` — just the dollar sign and a name.\n\n```powershell\n$vmName = "az104-vm-01"\n$vmCount = 3\n$isRunning = $true\n```\n\nPowerShell is **dynamically typed** — you don\'t declare a type up front, it figures it out from the value. You can check what something is at any point:\n\n```powershell\n$vmName.GetType().Name    # -> String\n$vmCount.GetType().Name   # -> Int32\n```\n\n## Common types you\'ll actually use\n\n| Type | Example | Notes |\n|---|---|---|\n| String | `"az104-vm-01"` | Text. Double quotes allow interpolation (below), single quotes don\'t. |\n| Int | `3` | Whole numbers. |\n| Bool | `$true` / `$false` | Note the `$` — they\'re variables, not keywords, unlike most languages. |\n| Array | `@("vm1", "vm2", "vm3")` | Ordered list of values. |\n| Hashtable | `@{ Name = "vm1"; Size = "Standard_B2s" }` | Key-value pairs — the closest thing to a Python dict. |\n\n## String interpolation\n\nDouble quotes let you drop a variable straight into a string. Single quotes treat everything literally.\n\n```powershell\n$env = "az104-training"\nWrite-Output "Deploying to $env"          # -> Deploying to az104-training\nWrite-Output \'Deploying to $env\'          # -> Deploying to $env  (literal, not substituted)\n```\n\nFor anything more complex than a bare variable name — a property, a method call, an expression — wrap it in `$()`:\n\n```powershell\n$vm = Get-AzVM -Name "az104-vm-01" -ResourceGroupName "rg-compute"\nWrite-Output "VM state: $($vm.ProvisioningState)"\n```\n\n## Arrays\n\n```powershell\n$vmNames = @("az104-vm-01", "az104-vm-02", "az104-vm-03")\n\n$vmNames[0]              # -> az104-vm-01  (zero-indexed, same as Python)\n$vmNames.Count            # -> 3\n$vmNames += "az104-vm-04" # append — creates a new array under the hood, arrays are fixed-size\n```\n\nThat last line matters: PowerShell arrays are fixed size. `+=` doesn\'t grow the array in place — it silently creates a new one and reassigns the variable. Fine for small automation scripts; worth knowing so it doesn\'t look like magic.\n\n## Hashtables\n\n```powershell\n$vmConfig = @{\n    Name         = "az104-vm-01"\n    Size         = "Standard_B2s"\n    ResourceGroup = "rg-compute"\n}\n\n$vmConfig.Name              # -> az104-vm-01\n$vmConfig["ResourceGroup"]  # -> rg-compute  (bracket access also works)\n```\n\nYou\'ll see hashtables constantly in Azure PowerShell — a lot of cmdlets accept a hashtable of tags or parameters instead of ten separate flags.\n\n## What\'s next\n\nLesson 3 covers the pipeline and objects — the concept that makes PowerShell behave differently from every shell you\'ve used before.\n',
    'powershell/lessons/03-pipeline-and-objects.md': '# Lesson 3 — The Pipeline and Objects\n\nThis is the concept that makes PowerShell genuinely different from Bash or a raw CLI, and it\'s worth slowing down on.\n\n## Cmdlet naming: Verb-Noun\n\nEvery built-in command follows **Verb-Noun**: `Get-AzVM`, `Set-AzVMSize`, `New-AzResourceGroup`, `Remove-AzVM`, `Start-AzVM`, `Stop-AzVM`. The verbs are a fixed, approved list (`Get-Verb` shows all of them), which means once you\'ve learned the pattern, you can often *guess* the right cmdlet name for something you haven\'t used yet.\n\n## Objects, not text\n\nRun this in Bash and you get a block of plain text you\'d have to parse with `grep`/`awk`/`cut` to pull one field out of. Run the PowerShell equivalent:\n\n```powershell\nGet-AzVM\n```\n\nand what comes back isn\'t text — it\'s a collection of full **objects**, each with named properties (`Name`, `ResourceGroupName`, `Location`, `ProvisioningState`, and dozens more). You don\'t parse anything. You just ask for the property you want:\n\n```powershell\n$vm = Get-AzVM -Name "az104-vm-01" -ResourceGroupName "rg-compute"\n$vm.Name              # -> az104-vm-01\n$vm.ProvisioningState # -> Succeeded\n```\n\nThis is the single biggest mental shift coming from Python or Bash: PowerShell cmdlets return live data structures, not printed strings.\n\n## Get-Member — seeing what an object actually contains\n\nYou rarely need to guess what properties exist. Pipe anything into `Get-Member` and it lists every property and method:\n\n```powershell\nGet-AzVM -Name "az104-vm-01" -ResourceGroupName "rg-compute" | Get-Member\n```\n\nThis is how you discover `.ProvisioningState`, `.HardwareProfile.VmSize`, and everything else — not by memorizing a reference, by asking the object directly.\n\n## The pipeline: `|`\n\nThe pipe character passes the *output object* of one cmdlet in as the *input* to the next. This is how you filter, sort, and transform without ever writing a loop by hand.\n\n```powershell\nGet-AzVM | Where-Object { $_.PowerState -eq "VM running" }\n```\n\n`$_` means "the current object flowing through the pipeline, right now." `Where-Object` runs its script block once per object and keeps only the ones where the block returns `$true`.\n\n## The core filtering/shaping cmdlets\n\n| Cmdlet | What it does |\n|---|---|\n| `Where-Object` | Filters — keeps objects matching a condition. |\n| `Select-Object` | Picks specific properties, or the first/last N objects. |\n| `Sort-Object` | Sorts by a property. |\n| `ForEach-Object` | Runs a script block once per object in the pipeline — for side effects, not filtering. |\n\n```powershell\nGet-AzVM |\n    Where-Object { $_.Location -eq "eastus" } |\n    Select-Object Name, ResourceGroupName, ProvisioningState |\n    Sort-Object Name\n```\n\nRead that as a sentence: get every VM, keep only the ones in East US, show just three fields, sort by name. Each stage only has to think about the one thing it does — that\'s the actual value of the pipeline over one dense line of code.\n\n## What\'s next\n\nLesson 4 covers control flow — `if`, loops, and the important distinction between the `foreach` keyword and the `ForEach-Object` cmdlet you just saw above.\n',
    'powershell/lessons/04-control-flow.md': '# Lesson 4 — Control Flow\n\n## if / elseif / else\n\n```powershell\n$vmCount = 3\n\nif ($vmCount -eq 0) {\n    Write-Output "No VMs found"\n} elseif ($vmCount -gt 5) {\n    Write-Output "More than expected — check for stragglers"\n} else {\n    Write-Output "$vmCount VMs found"\n}\n```\n\nComparison operators are words, not symbols — this trips up almost everyone coming from another language:\n\n| Operator | Meaning |\n|---|---|\n| `-eq` | equals |\n| `-ne` | not equals |\n| `-gt` / `-lt` | greater than / less than |\n| `-ge` / `-le` | greater or equal / less or equal |\n| `-like` | wildcard string match (`"az104*"`) |\n| `-match` | regex match |\n| `-contains` | does a collection contain this value |\n\n## switch\n\nFor checking one value against several possibilities, `switch` reads cleaner than a chain of `elseif`:\n\n```powershell\nswitch ($vm.PowerState) {\n    "VM running"      { Write-Output "Active" }\n    "VM deallocated"  { Write-Output "Stopped — no compute charge" }\n    "VM stopped"      { Write-Output "Stopped — still billing" }\n    default           { Write-Output "Unknown state" }\n}\n```\n\n## foreach (the keyword) vs. ForEach-Object (the cmdlet)\n\nThese look similar and do similar things, but they\'re not the same tool, and the distinction is worth being precise about:\n\n- **`foreach`** is a language keyword. It loops over a collection that\'s already fully loaded in memory.\n- **`ForEach-Object`** is a cmdlet, meant for the pipeline (see Lesson 3) — it processes one object at a time *as it flows through*, without needing the whole collection loaded first.\n\n```powershell\n# foreach — collection already in a variable\n$vms = Get-AzVM\nforeach ($vm in $vms) {\n    Write-Output $vm.Name\n}\n\n# ForEach-Object — inside a pipeline\nGet-AzVM | ForEach-Object { Write-Output $_.Name }\n```\n\nFor small scripts against a handful of Azure resources, either works and the performance difference is irrelevant. Use `foreach` when you already have the data in a variable and want to act on it; use `ForEach-Object` when you\'re chaining it directly off another cmdlet\'s output.\n\n## for and while\n\nLess common in Azure automation scripts specifically, but standard tools:\n\n```powershell\nfor ($i = 0; $i -lt 5; $i++) {\n    Write-Output "Iteration $i"\n}\n\n$attempts = 0\nwhile ($attempts -lt 3) {\n    Write-Output "Attempt $attempts"\n    $attempts++\n}\n```\n\n## break and continue\n\n```powershell\nforeach ($vm in $vms) {\n    if ($vm.ProvisioningState -eq "Failed") {\n        continue    # skip this one, move to the next\n    }\n    if ($vm.Name -eq "critical-vm") {\n        break       # stop the loop entirely\n    }\n    Write-Output $vm.Name\n}\n```\n\n## What\'s next\n\nLesson 5 covers functions — how to package a piece of logic like the ones above so you can reuse it instead of retyping it.\n',
    'powershell/lessons/05-functions-and-parameters.md': '# Lesson 5 — Functions and Parameters\n\n## Basic function\n\n```powershell\nfunction Get-VmSummary {\n    param(\n        [string]$ResourceGroupName\n    )\n\n    $vms = Get-AzVM -ResourceGroupName $ResourceGroupName\n    foreach ($vm in $vms) {\n        Write-Output "$($vm.Name): $($vm.ProvisioningState)"\n    }\n}\n```\n\nCall it like a built-in cmdlet:\n\n```powershell\nGet-VmSummary -ResourceGroupName "rg-compute"\n```\n\nFunctions get named the same Verb-Noun way as real cmdlets — it\'s a convention, not a hard requirement, but sticking to it means your own functions read consistently with everything else in the language, and `Get-Verb` will tell you which verb actually fits what the function does.\n\n## The param() block\n\n`param()` at the top of a function (or a whole script — see Lesson 7) declares what it accepts, same idea as arguments in a Python `def`.\n\n```powershell\nfunction New-VmTag {\n    param(\n        [string]$Key,\n        [string]$Value = "untagged",   # default value if not supplied\n        [Parameter(Mandatory = $true)]\n        [string]$ResourceId              # must be supplied or the function refuses to run\n    )\n    # ...\n}\n```\n\n- Giving a parameter a default value makes it optional.\n- `[Parameter(Mandatory = $true)]` makes PowerShell prompt for the value (or error out in a non-interactive script) if it\'s missing, instead of quietly running with a blank value — worth using on anything a script genuinely can\'t function without.\n- `[string]` before the parameter name is a type constraint — PowerShell will reject a call that passes the wrong type, catching a mistake at the call site instead of somewhere deeper in the function.\n\n## Return values\n\nPowerShell doesn\'t require an explicit `return` the way Python does — anything not captured or suppressed gets written to the output pipeline automatically. `return` still works and is useful for exiting early:\n\n```powershell\nfunction Test-IsRunning {\n    param([string]$VmName, [string]$ResourceGroupName)\n\n    $vm = Get-AzVM -Name $VmName -ResourceGroupName $ResourceGroupName -Status\n    if ($vm.PowerState -eq "VM running") {\n        return $true\n    }\n    return $false\n}\n```\n\n## Calling with named vs. positional parameters\n\n```powershell\nGet-VmSummary -ResourceGroupName "rg-compute"   # named — explicit, readable, order doesn\'t matter\nGet-VmSummary "rg-compute"                       # positional — works if only one param, gets messy fast with more\n```\n\nDefault to named parameters once a function takes more than one argument. It\'s the difference between a script that\'s self-documenting six months from now and one you have to re-derive from the function definition every time.\n\n## Advanced functions — [CmdletBinding()]\n\nAdding `[CmdletBinding()]` above `param()` turns a plain function into something that behaves like a real cmdlet — it gains support for common parameters like `-Verbose` and `-WhatIf` (the same `-WhatIf` pattern behind `az deployment group what-if`, if that\'s a familiar concept from the Bicep side).\n\n```powershell\nfunction Remove-OldSnapshot {\n    [CmdletBinding(SupportsShouldProcess = $true)]\n    param(\n        [Parameter(Mandatory = $true)]\n        [string]$SnapshotName\n    )\n\n    if ($PSCmdlet.ShouldProcess($SnapshotName, "Remove snapshot")) {\n        Remove-AzSnapshot -SnapshotName $SnapshotName -Force\n    }\n}\n```\n\n`SupportsShouldProcess` plus `ShouldProcess` is what gives a function real `-WhatIf` and `-Confirm` support — genuinely worth having on anything that deletes or modifies a resource, not just queries one.\n\n## What\'s next\n\nLesson 6 covers connecting to Azure itself — authentication, context, and the Az and Microsoft Graph modules that everything from here on builds against.\n',
    'powershell/lessons/06-connecting-to-azure.md': '# Lesson 6 — Connecting to Azure\n\n## Installing the Az module\n\nThe Az module is Microsoft\'s current PowerShell module for managing Azure resources — the older `AzureRM` module is deprecated and shouldn\'t be used. One-time install, per machine:\n\n```powershell\nInstall-Module Az -Scope CurrentUser -Repository PSGallery -Force\n```\n\n`-Scope CurrentUser` avoids needing admin/sudo — installs into your own profile, not system-wide.\n\n## Connecting\n\n```powershell\nConnect-AzAccount\n```\n\nThis opens a browser window for an interactive login. After signing in, PowerShell holds an authenticated **context** — the combination of account, tenant, and subscription it\'s currently operating against.\n\n```powershell\nGet-AzContext                    # shows what you\'re currently connected as/to\nGet-AzContext -ListAvailable     # every subscription context available to you\nSet-AzContext -Subscription "gq1" # switch which subscription commands target\n```\n\nAlways check `Get-AzContext` at the start of a session before running anything — commands silently run against whatever subscription the context currently points to, which isn\'t always the one you meant.\n\n## What a "session" means in practice\n\nThe authenticated context lives for that terminal session. Close the terminal, and you\'ll need to `Connect-AzAccount` again next time — same idea as re-authenticating `az login` for the CLI side of this repo. (Newer versions of the Az module have gotten better at persisting context across terminal tabs within the same login session, but don\'t rely on that — verify with `Get-AzContext` rather than assume you\'re still connected.)\n\nFor anything beyond interactive personal use — a script meant to run unattended — authentication switches to a **service principal** (an application identity instead of a personal login) or a **managed identity** (an identity Azure assigns automatically to a resource like a VM or Function App, so there\'s no secret to store at all). Not needed for the manual, weekend-driven scripts this repo is building right now — worth knowing the concept exists for when automation moves toward something scheduled or unattended.\n\n## Microsoft Graph — for Entra ID\n\n`Get-AzADUser` and similar exist, but the modern, fuller way to query Entra ID (users, groups, roles) from PowerShell is the **Microsoft Graph PowerShell SDK** — a separate module from Az, talking to the Graph API rather than Azure Resource Manager.\n\n```powershell\nInstall-Module Microsoft.Graph -Scope CurrentUser -Force\n```\n\n```powershell\nConnect-MgGraph -Scopes \'User.Read.All\'\n```\n\nGraph uses **scopes** instead of a subscription context — each scope is a specific permission (`User.Read.All`, `Group.Read.All`, etc.), and you request only what a given script actually needs. If a command fails with a permissions error, it usually means the scope you connected with doesn\'t cover it — reconnect with the broader scope rather than guessing.\n\n```powershell\nGet-MgUser -Top 5\nGet-MgUser -UserId "someone@yourtenant.onmicrosoft.com" -Property DisplayName, UserPrincipalName\n```\n\n`Find-MgGraphCommand -Command Get-MgUser` will tell you exactly which scopes a given Graph cmdlet needs, if you\'re not sure what to request.\n\n## Cheatsheet — cmdlets by AZ-104 phase\n\n| Phase | Cmdlets |\n|---|---|\n| Compute/Governance | `Get-AzVM`, `Get-AzVMSize`, `Get-AzPolicyDefinition`, `Get-AzManagementGroup` |\n| Networking | `Get-AzVirtualNetwork`, `Get-AzNetworkSecurityGroup`, `Get-AzLoadBalancer`, `Get-AzApplicationGateway` |\n| Storage | `Get-AzStorageAccount`, `Get-AzStorageContainer`, `Get-AzStorageBlob` |\n| Identity | `Get-MgUser`, `Get-MgGroup`, `Get-AzRoleAssignment` |\n| Monitoring | `Get-AzMetric`, `Get-AzLog`, `Get-AzRecoveryServicesVault` |\n\n## What\'s next\n\nLesson 7 puts everything so far together — proper script structure, error handling, and a full worked automation script built line by line.\n',
    'powershell/lessons/07-script-structure-and-first-automation-script.md': '# Lesson 7 — Script Structure, Error Handling, and Your First Automation Script\n\nEverything from Lessons 1–6 comes together here. By the end of this one you\'ll have a template you can reuse for every automation script going forward.\n\n## Comment-based help\n\nA block comment at the very top of a script, in a specific format PowerShell recognizes, so `Get-Help ./your-script.ps1` works on your own scripts exactly like it does on built-in cmdlets:\n\n```powershell\n<#\n.SYNOPSIS\n    Reports the power state of every VM in a resource group.\n.DESCRIPTION\n    Connects to Azure, queries all VMs in the given resource group,\n    and prints each VM\'s name and current power state.\n.PARAMETER ResourceGroupName\n    The resource group to query.\n.EXAMPLE\n    ./Get-VmPowerReport.ps1 -ResourceGroupName "rg-compute"\n#>\n```\n\n## Script-level param()\n\nSame concept as a function\'s `param()` block, but for the whole script — it becomes the script\'s command-line interface.\n\n```powershell\nparam(\n    [Parameter(Mandatory = $true)]\n    [string]$ResourceGroupName\n)\n```\n\n## Error handling — try/catch/finally\n\nPowerShell has two kinds of errors: **terminating** (stops execution, catchable) and **non-terminating** (prints a warning but keeps going, by default *not* caught by `try/catch`). Most Az cmdlet failures are non-terminating unless you force them to stop:\n\n```powershell\ntry {\n    $vms = Get-AzVM -ResourceGroupName $ResourceGroupName -ErrorAction Stop\n}\ncatch {\n    Write-Error "Failed to query resource group \'$ResourceGroupName\': $_"\n    exit 1\n}\nfinally {\n    Write-Verbose "Query attempt finished."\n}\n```\n\n`-ErrorAction Stop` is the important, easy-to-miss detail — without it, a failed Az cmdlet often just writes a red warning to the screen and lets the rest of the script run anyway, which is rarely what you want in something meant to run unattended.\n\n## Write-Output vs. Write-Host vs. Write-Verbose vs. Write-Error\n\n| Cmdlet | Use it for |\n|---|---|\n| `Write-Output` | The actual result — goes into the pipeline, can be captured or piped further. Default choice. |\n| `Write-Host` | Console-only text, can\'t be redirected or captured — status messages meant purely for a human watching. |\n| `Write-Verbose` | Extra detail, only shown when the script is run with `-Verbose`. Good for step-by-step tracing without cluttering normal output. |\n| `Write-Error` | A non-terminating error message — use alongside `exit 1`, not instead of it, if the script should actually stop. |\n\n## Exit codes\n\n```powershell\nexit 0   # success\nexit 1   # failure\n```\n\nDoesn\'t matter for a script you run and read by eye. Matters the moment anything else — a CI pipeline, a scheduled task, another script — calls this one and needs to know whether it succeeded without parsing output text.\n\n---\n\n## Full worked example: `Get-VmPowerReport.ps1`\n\nBuilt up in pieces, then shown whole.\n\n**Piece 1 — the interface.** What does this script need to run, and what does it promise to do?\n\n```powershell\n<#\n.SYNOPSIS\n    Reports the power state of every VM in a resource group.\n#>\nparam(\n    [Parameter(Mandatory = $true)]\n    [string]$ResourceGroupName\n)\n```\n\n**Piece 2 — confirm the session before doing anything else.** Don\'t let a script run five minutes of work only to fail on a missing login at the end.\n\n```powershell\nif (-not (Get-AzContext)) {\n    Write-Error "Not connected to Azure. Run Connect-AzAccount first."\n    exit 1\n}\n```\n\n**Piece 3 — do the actual work, wrapped in error handling.**\n\n```powershell\ntry {\n    $vms = Get-AzVM -ResourceGroupName $ResourceGroupName -Status -ErrorAction Stop\n}\ncatch {\n    Write-Error "Could not query resource group \'$ResourceGroupName\': $_"\n    exit 1\n}\n```\n\n**Piece 4 — handle the empty case explicitly.** A script that silently prints nothing when a resource group has no VMs looks broken, even when it\'s working correctly.\n\n```powershell\nif ($vms.Count -eq 0) {\n    Write-Output "No VMs found in resource group \'$ResourceGroupName\'."\n    exit 0\n}\n```\n\n**Piece 5 — the report itself, using the pipeline concepts from Lesson 3.**\n\n```powershell\n$vms |\n    Select-Object Name, @{Name = "PowerState"; Expression = { $_.PowerState } } |\n    Sort-Object Name |\n    Format-Table -AutoSize\n```\n\nThe `@{Name=...; Expression=...}` piece is a **calculated property** — `Select-Object` normally just picks existing properties by name, but this syntax lets you define a new column instead, here just aliasing `PowerState` for a cleaner table header. You\'ll see this pattern often once you start shaping output for readability.\n\n**Whole script, assembled:**\n\n```powershell\n<#\n.SYNOPSIS\n    Reports the power state of every VM in a resource group.\n.PARAMETER ResourceGroupName\n    The resource group to query.\n.EXAMPLE\n    ./Get-VmPowerReport.ps1 -ResourceGroupName "rg-compute"\n#>\nparam(\n    [Parameter(Mandatory = $true)]\n    [string]$ResourceGroupName\n)\n\nif (-not (Get-AzContext)) {\n    Write-Error "Not connected to Azure. Run Connect-AzAccount first."\n    exit 1\n}\n\ntry {\n    $vms = Get-AzVM -ResourceGroupName $ResourceGroupName -Status -ErrorAction Stop\n}\ncatch {\n    Write-Error "Could not query resource group \'$ResourceGroupName\': $_"\n    exit 1\n}\n\nif ($vms.Count -eq 0) {\n    Write-Output "No VMs found in resource group \'$ResourceGroupName\'."\n    exit 0\n}\n\n$vms |\n    Select-Object Name, @{Name = "PowerState"; Expression = { $_.PowerState } } |\n    Sort-Object Name |\n    Format-Table -AutoSize\n```\n\n## Closing out a script — your checklist\n\n- Run it against a real resource group and confirm the output matches the Portal/CLI.\n- Confirm it doesn\'t error on an empty result — should print a clear message, not crash.\n- No hardcoded subscription IDs, resource group names, or secrets — everything that changes between runs goes through `param()`.\n- Comment-based help block at the top.\n- Commit it once it does what it\'s supposed to.\n\n## What\'s next\n\n`GLOSSARY.md` in this folder has every term from all seven lessons in one place. From here, the weekly rhythm is the [weekend study guide](../powershell-weekend-study-guide.md) — same tools, applied to that week\'s Azure lab.\n',
    'powershell/scripts/README.md': "# PowerShell Scripts\n\nYour own weekly automation scripts go here, one per weekend, built from the pattern in\n`lessons/07-script-structure-and-first-automation-script.md`.\n\nNaming suggestion: `<verb>-<what-it-does>.ps1`, matching PowerShell's own Verb-Noun convention\n(e.g. `Get-VmPowerReport.ps1`, `New-PolicyAssignmentCheck.ps1`).\n",
}


def main():
    created = []
    skipped = []

    for relative_path, content in FILES.items():
        target = REPO_ROOT / relative_path
        target.parent.mkdir(parents=True, exist_ok=True)

        if target.exists():
            skipped.append(relative_path)
            continue

        target.write_text(content, encoding="utf-8")
        created.append(relative_path)

    print(f"Repo root resolved to: {REPO_ROOT}")
    print()

    if created:
        print(f"Created ({len(created)}):")
        for path in created:
            print(f"  + {path}")

    if skipped:
        print(f"\nSkipped, already exists ({len(skipped)}):")
        for path in skipped:
            print(f"  = {path}")

    if not created and not skipped:
        print("Nothing to do.")


if __name__ == "__main__":
    main()